import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_src = r"""
#include <torch/extension.h>
torch::Tensor bn2d_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                           torch::Tensor running_mean, torch::Tensor running_var,
                           torch::Tensor num_batches_tracked,
                           double eps, double momentum, bool training);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BN_INIT_STATS 0
#define BN_REDUCE     1
#define BN_NORM_TRAIN 2
#define BN_NORM_EVAL  3

__global__ void bn2d_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    float* __restrict__ stats,
    long long N, long long C, long long S,
    float eps, float momentum,
    int mode, int blocks_per_channel, int update_nbt)
{
    const long long total = N * C * S;
    const long long m = N * S;

    if (mode == BN_INIT_STATS) {
        long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
        long long stride = (long long)gridDim.x * blockDim.x;
        for (long long i = tid; i < 2LL * C; i += stride) {
            stats[i] = 0.0f;
        }
        return;
    }

    if (mode == BN_REDUCE) {
        const int bid = blockIdx.x;
        const int c = bid / blocks_per_channel;
        const int part = bid - c * blocks_per_channel;
        const long long base = (long long)c * m;

        float local_sum = 0.0f;
        float local_sumsq = 0.0f;
        const long long start = (long long)part * blockDim.x + threadIdx.x;
        const long long stride = (long long)blocks_per_channel * blockDim.x;
        if ((m & 3LL) == 0) {
            const float4* x4 = reinterpret_cast<const float4*>(x + base);
            const long long m4 = m >> 2;
            for (long long off = start; off < m4; off += stride) {
                // Reduce pass: cache-all loads keep this channel slab resident in L2
                // so the immediately-following normalize pass re-reads it from L2, not DRAM.
                float4 v = __ldca(&x4[off]);
                local_sum += v.x + v.y + v.z + v.w;
                local_sumsq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
            }
        } else {
            for (long long off = start; off < m; off += stride) {
                float v = __ldca(&x[base + off]);
                local_sum += v;
                local_sumsq += v * v;
            }
        }

        __shared__ float sh_sum[256];
        __shared__ float sh_sumsq[256];
        sh_sum[threadIdx.x] = local_sum;
        sh_sumsq[threadIdx.x] = local_sumsq;
        __syncthreads();

        for (int s = blockDim.x / 2; s > 32; s >>= 1) {
            if (threadIdx.x < s) {
                sh_sum[threadIdx.x] += sh_sum[threadIdx.x + s];
                sh_sumsq[threadIdx.x] += sh_sumsq[threadIdx.x + s];
            }
            __syncthreads();
        }

        if (threadIdx.x < 32) {
            float a = sh_sum[threadIdx.x];
            float b = sh_sumsq[threadIdx.x];
            for (int off = 16; off > 0; off >>= 1) {
                a += __shfl_down_sync(0xffffffffu, a, off);
                b += __shfl_down_sync(0xffffffffu, b, off);
            }
            if (threadIdx.x == 0) {
                atomicAdd(&stats[2 * c], a);
                atomicAdd(&stats[2 * c + 1], b);
            }
        }
        return;
    }

    long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)gridDim.x * blockDim.x;
    // Dynamic shared memory staging of per-channel mean/invstd (reused by all N*S elements).
    // For norm modes, blocks_per_channel is repurposed as a use_smem flag.
    extern __shared__ float sdata[];
    if (mode == BN_NORM_TRAIN) {
        if (update_nbt && tid == 0) {
            atomicAdd((unsigned long long*)num_batches_tracked, 1ULL);
        }
        if (blocks_per_channel) {
            float* smean = sdata;
            float* sinvstd = sdata + C;
            for (long long c = threadIdx.x; c < C; c += blockDim.x) {
                float sum = stats[2 * c];
                float sumsq = stats[2 * c + 1];
                float mean = sum / (float)m;
                float var = sumsq / (float)m - mean * mean;
                var = fmaxf(var, 0.0f);
                smean[c] = mean;
                sinvstd[c] = rsqrtf(var + eps);
            }
            __syncthreads();
            if ((S & 3LL) == 0 && (total & 3LL) == 0) {
                const float4* x4 = reinterpret_cast<const float4*>(x);
                float4* y4 = reinterpret_cast<float4*>(y);
                const long long total4 = total >> 2;
                for (long long idx = tid; idx < total4; idx += stride) {
                    long long base = idx << 2;
                    long long nc = base / S;
                    int c = (int)(nc % C);
                    float mean = smean[c];
                    float invstd = sinvstd[c];
                    float w = weight[c];
                    float b = bias[c];
                    float4 xv = __ldcs(&x4[idx]);
                    float4 yv;
                    yv.x = (xv.x - mean) * invstd * w + b;
                    yv.y = (xv.y - mean) * invstd * w + b;
                    yv.z = (xv.z - mean) * invstd * w + b;
                    yv.w = (xv.w - mean) * invstd * w + b;
                    __stcs(&y4[idx], yv);
                }
            } else {
                for (long long idx = tid; idx < total; idx += stride) {
                    long long nc = idx / S;
                    int c = (int)(nc % C);
                    float mean = smean[c];
                    float invstd = sinvstd[c];
                    __stcs(&y[idx], (__ldcs(&x[idx]) - mean) * invstd * weight[c] + bias[c]);
                }
            }
            if (tid < C) {
                int c = (int)tid;
                float sum = stats[2 * c];
                float sumsq = stats[2 * c + 1];
                float mean = sum / (float)m;
                float var = sumsq / (float)m - mean * mean;
                var = fmaxf(var, 0.0f);
                float unbiased = (m > 1) ? (var * (float)m / (float)(m - 1)) : var;
                running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
                running_var[c]  = (1.0f - momentum) * running_var[c]  + momentum * unbiased;
            }
            return;
        }
        if ((S & 3LL) == 0 && (total & 3LL) == 0) {
            const float4* x4 = reinterpret_cast<const float4*>(x);
            float4* y4 = reinterpret_cast<float4*>(y);
            const long long total4 = total >> 2;
            for (long long idx = tid; idx < total4; idx += stride) {
                long long base = idx << 2;
                long long nc = base / S;
                int c = (int)(nc % C);
                float sum = stats[2 * c];
                float sumsq = stats[2 * c + 1];
                float mean = sum / (float)m;
                float var = sumsq / (float)m - mean * mean;
                var = fmaxf(var, 0.0f);
                float invstd = rsqrtf(var + eps);
                float w = weight[c];
                float b = bias[c];
                float4 xv = __ldcs(&x4[idx]);
                float4 yv;
                yv.x = (xv.x - mean) * invstd * w + b;
                yv.y = (xv.y - mean) * invstd * w + b;
                yv.z = (xv.z - mean) * invstd * w + b;
                yv.w = (xv.w - mean) * invstd * w + b;
                __stcs(&y4[idx], yv);
            }
            if (tid < C) {
                int c = (int)tid;
                float sum = stats[2 * c];
                float sumsq = stats[2 * c + 1];
                float mean = sum / (float)m;
                float var = sumsq / (float)m - mean * mean;
                var = fmaxf(var, 0.0f);
                float unbiased = (m > 1) ? (var * (float)m / (float)(m - 1)) : var;
                running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
                running_var[c]  = (1.0f - momentum) * running_var[c]  + momentum * unbiased;
            }
        } else {
            for (long long idx = tid; idx < total; idx += stride) {
                long long nc = idx / S;
                int c = (int)(nc % C);
                float sum = stats[2 * c];
                float sumsq = stats[2 * c + 1];
                float mean = sum / (float)m;
                float var = sumsq / (float)m - mean * mean;
                var = fmaxf(var, 0.0f);
                float invstd = rsqrtf(var + eps);
                __stcs(&y[idx], (__ldcs(&x[idx]) - mean) * invstd * weight[c] + bias[c]);
                if (idx < C) {
                    float unbiased = (m > 1) ? (var * (float)m / (float)(m - 1)) : var;
                    running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
                    running_var[c]  = (1.0f - momentum) * running_var[c]  + momentum * unbiased;
                }
            }
        }
        return;
    }
    // BN_NORM_EVAL
    if (blocks_per_channel) {
        float* smean = sdata;
        float* sinvstd = sdata + C;
        for (long long c = threadIdx.x; c < C; c += blockDim.x) {
            smean[c] = running_mean[c];
            sinvstd[c] = rsqrtf(running_var[c] + eps);
        }
        __syncthreads();
        if ((S & 3LL) == 0 && (total & 3LL) == 0) {
            const float4* x4 = reinterpret_cast<const float4*>(x);
            float4* y4 = reinterpret_cast<float4*>(y);
            const long long total4 = total >> 2;
            for (long long idx = tid; idx < total4; idx += stride) {
                long long base = idx << 2;
                long long nc = base / S;
                int c = (int)(nc % C);
                float invstd = sinvstd[c];
                float rm = smean[c];
                float w = weight[c];
                float b = bias[c];
                float4 xv = __ldcs(&x4[idx]);
                float4 yv;
                yv.x = (xv.x - rm) * invstd * w + b;
                yv.y = (xv.y - rm) * invstd * w + b;
                yv.z = (xv.z - rm) * invstd * w + b;
                yv.w = (xv.w - rm) * invstd * w + b;
                __stcs(&y4[idx], yv);
            }
        } else {
            for (long long idx = tid; idx < total; idx += stride) {
                long long nc = idx / S;
                int c = (int)(nc % C);
                float invstd = sinvstd[c];
                __stcs(&y[idx], (__ldcs(&x[idx]) - smean[c]) * invstd * weight[c] + bias[c]);
            }
        }
        return;
    }
    if ((S & 3LL) == 0 && (total & 3LL) == 0) {
        const float4* x4 = reinterpret_cast<const float4*>(x);
        float4* y4 = reinterpret_cast<float4*>(y);
        const long long total4 = total >> 2;
        for (long long idx = tid; idx < total4; idx += stride) {
            long long base = idx << 2;
            long long nc = base / S;
            int c = (int)(nc % C);
            float invstd = rsqrtf(running_var[c] + eps);
            float rm = running_mean[c];
            float w = weight[c];
            float b = bias[c];
            float4 xv = __ldcs(&x4[idx]);
            float4 yv;
            yv.x = (xv.x - rm) * invstd * w + b;
            yv.y = (xv.y - rm) * invstd * w + b;
            yv.z = (xv.z - rm) * invstd * w + b;
            yv.w = (xv.w - rm) * invstd * w + b;
            __stcs(&y4[idx], yv);
        }
        return;
    }
    for (long long idx = tid; idx < total; idx += stride) {
        long long nc = idx / S;
        int c = (int)(nc % C);
        float invstd = rsqrtf(running_var[c] + eps);
        __stcs(&y[idx], (__ldcs(&x[idx]) - running_mean[c]) * invstd * weight[c] + bias[c]);
    }
}

torch::Tensor bn2d_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                           torch::Tensor running_mean, torch::Tensor running_var,
                           torch::Tensor num_batches_tracked,
                           double eps, double momentum, bool training)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "affine params must be CUDA");
    TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");

    const c10::cuda::CUDAGuard guard(x.device());
    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);

    const long long N = xc.size(0);
    const long long C = xc.size(1);
    const long long H = xc.size(2);
    const long long W = xc.size(3);
    const long long S = H * W;
    const long long total = N * C * S;

    auto stream = at::cuda::getCurrentCUDAStream();
    const int block = 256;
    const int norm_block = 512;

    float* x_ptr = xc.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    float* w_ptr = weight.data_ptr<float>();
    float* b_ptr = bias.data_ptr<float>();
    float* rm_ptr = running_mean.data_ptr<float>();
    float* rv_ptr = running_var.data_ptr<float>();
    int64_t* nbt_ptr = num_batches_tracked.data_ptr<int64_t>();

    if (training) {
        auto stats = torch::empty({2 * C}, xc.options());
        float* stats_ptr = stats.data_ptr<float>();
        cudaMemsetAsync(stats_ptr, 0, (size_t)(2 * C) * sizeof(float), stream);
        // Single multi-channel reduce launch + single full-tensor normalize launch:
        // collapses the serialized per-channel loop (2*C kernel launches, each
        // with a partial-wave tail) into 2 launches. The kernel already supports
        // multi-channel reduction via blocks_per_channel and full-tensor normalize.
        const int reduce_bpc = 1024;
        dim3 reduce_grid((unsigned)(C * (long long)reduce_bpc));
        bn2d_kernel<<<reduce_grid, block, 0, stream>>>(
            x_ptr, y_ptr, w_ptr, b_ptr, rm_ptr, rv_ptr, nbt_ptr, stats_ptr,
            N, C, S, (float)eps, (float)momentum, BN_REDUCE, reduce_bpc, 0);
        long long vec_items = (((S & 3LL) == 0) && ((total & 3LL) == 0)) ? (total >> 2) : total;
        long long want_blocks = (vec_items + norm_block - 1) / norm_block;
        int norm_grid = (int)std::min<long long>(want_blocks, 65536LL);
        if (norm_grid < 1) norm_grid = 1;
        size_t smem_bytes = 0;
        int use_smem = 0;
        if ((size_t)(2 * C) * sizeof(float) <= 48 * 1024) {
            smem_bytes = (size_t)(2 * C) * sizeof(float);
            use_smem = 1;
        }
        bn2d_kernel<<<norm_grid, norm_block, smem_bytes, stream>>>(
            x_ptr, y_ptr, w_ptr, b_ptr, rm_ptr, rv_ptr, nbt_ptr, stats_ptr,
            N, C, S, (float)eps, (float)momentum, BN_NORM_TRAIN, use_smem, 1);
    } else {
        long long want_blocks = (total + norm_block - 1) / norm_block;
        int norm_grid = (int)std::min<long long>(want_blocks, 65536LL);
        if (norm_grid < 1) norm_grid = 1;
        size_t smem_bytes = 0;
        int use_smem = 0;
        if ((size_t)(2 * C) * sizeof(float) <= 48 * 1024) {
            smem_bytes = (size_t)(2 * C) * sizeof(float);
            use_smem = 1;
        }
        bn2d_kernel<<<norm_grid, norm_block, smem_bytes, stream>>>(
            x_ptr, y_ptr, w_ptr, b_ptr, rm_ptr, rv_ptr, nbt_ptr, nullptr,
            N, C, S, (float)eps, (float)momentum, BN_NORM_EVAL, use_smem, 0);
    }

    return y;
}
"""

_bn_ext = load_inline(
    name="bn2d_custom_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["bn2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.zeros((), dtype=torch.long))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _bn_ext.bn2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.num_batches_tracked,
            self.eps,
            self.momentum,
            self.training,
        )

